    bronze_forgecoalraketooth = { name = "Bronast zobje za grebalce oglja", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast zobje za grebalce oglja za kovace." },
    silver_forgecoalraketooth = { name = "Srebrn zobje za grebalce oglja", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn zobje za grebalce oglja za kovace." },
    gilded_forgecoalraketooth = { name = "Pozlačen zobje za grebalce oglja", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen zobje za grebalce oglja za kovace." },
    jewel_set_forgecoalraketooth = { name = "Draguljast zobje za grebalce oglja", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast zobje za grebalce oglja za kovace." },
