}
ForgeCoalRakeToothMaker.ironStock=18; ForgeCoalRakeToothMaker.bronzeStock=14; ForgeCoalRakeToothMaker.woodStock=10; ForgeCoalRakeToothMaker.leatherStock=8; ForgeCoalRakeToothMaker.silverStock=8; ForgeCoalRakeToothMaker.goldStock=6; ForgeCoalRakeToothMaker.jewelStock=4; ForgeCoalRakeToothMaker.pearlStock=4
ForgeCoalRakeToothMaker.productStock = {}; ForgeCoalRakeToothMaker.buildings = {}; ForgeCoalRakeToothMaker.maker = nil; ForgeCoalRakeToothMaker.activeMaking = {}; ForgeCoalRakeToothMaker.totalProducts = 0; ForgeCoalRakeToothMaker.dayTimer = 0
function ForgeCoalRakeToothMaker.init() ForgeCoalRakeToothMaker.ironStock=18; ForgeCoalRakeToothMaker.bronzeStock=14; ForgeCoalRakeToothMaker.woodStock=10; ForgeCoalRakeToothMaker.leatherStock=8; ForgeCoalRakeToothMaker.silverStock=8; ForgeCoalRakeToothMaker.goldStock=6; ForgeCoalRakeToothMaker.jewelStock=4; ForgeCoalRakeToothMaker.pearlStock=4; ForgeCoalRakeToothMaker.productStock={}; ForgeCoalRakeToothMaker.buildings={}; ForgeCoalRakeToothMaker.maker=nil; ForgeCoalRakeToothMaker.activeMaking={}; ForgeCoalRakeToothMaker.totalProducts=0; ForgeCoalRakeToothMaker.dayTimer=0; print("[ForgeCoalRakeToothMaker] Royal Forge Coal Rake Tooth Maker System initialized (6 products, 4 buildings)") end
function ForgeCoalRakeToothMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ForgeCoalRakeToothMaker.maker={name=n or ("Zobnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zobnik najet: %s (spretnost: %d)",ForgeCoalRakeToothMaker.maker.name,s),"success") end; return true end
function ForgeCoalRakeToothMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ForgeCoalRakeToothMaker.build(id) local ok,e=ForgeCoalRakeToothMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ForgeCoalRakeToothMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ForgeCoalRakeToothMaker.getQualityBonus() local b=0; for _,bd in ipairs(ForgeCoalRakeToothMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ForgeCoalRakeToothMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and ForgeCoalRakeToothMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and ForgeCoalRakeToothMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and ForgeCoalRakeToothMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and ForgeCoalRakeToothMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ForgeCoalRakeToothMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ForgeCoalRakeToothMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ForgeCoalRakeToothMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ForgeCoalRakeToothMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ForgeCoalRakeToothMaker.buildings==0 then return false,"Potrebna zobna delavnica" end; if not ForgeCoalRakeToothMaker.maker then return false,"Potreben zobnik" end; return true end
function ForgeCoalRakeToothMaker.make(pt,qty) qty=qty or 1; local ok,e=ForgeCoalRakeToothMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then ForgeCoalRakeToothMaker.ironStock=ForgeCoalRakeToothMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then ForgeCoalRakeToothMaker.bronzeStock=ForgeCoalRakeToothMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then ForgeCoalRakeToothMaker.woodStock=ForgeCoalRakeToothMaker.woodStock-d.woodCost*qty end; if d.leatherCost then ForgeCoalRakeToothMaker.leatherStock=ForgeCoalRakeToothMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ForgeCoalRakeToothMaker.silverStock=ForgeCoalRakeToothMaker.silverStock-d.silverCost*qty end; if d.goldCost then ForgeCoalRakeToothMaker.goldStock=ForgeCoalRakeToothMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ForgeCoalRakeToothMaker.jewelStock=ForgeCoalRakeToothMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ForgeCoalRakeToothMaker.pearlStock=ForgeCoalRakeToothMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ForgeCoalRakeToothMaker.maker then t=math.max(1,t-math.floor(ForgeCoalRakeToothMaker.maker.skill/13)) end; table.insert(ForgeCoalRakeToothMaker.activeMaking,{id="forgecoalraketooth_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ForgeCoalRakeToothMaker.completeMaking(m) local q=1.0+(ForgeCoalRakeToothMaker.getQualityBonus()/100); if ForgeCoalRakeToothMaker.maker then q=q+(ForgeCoalRakeToothMaker.maker.skill/140) end; q=math.min(2.5,q); ForgeCoalRakeToothMaker.productStock[m.productType]=(ForgeCoalRakeToothMaker.productStock[m.productType] or 0)+m.quantity; ForgeCoalRakeToothMaker.totalProducts=ForgeCoalRakeToothMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ForgeCoalRakeToothMaker.maker then ForgeCoalRakeToothMaker.maker.itemsMade=ForgeCoalRakeToothMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ForgeCoalRakeToothMaker.maker.skill=math.min(100,ForgeCoalRakeToothMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zob izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"forgecoalraketooth.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function ForgeCoalRakeToothMaker.update(dt) if not _G.state then return end; ForgeCoalRakeToothMaker.dayTimer=ForgeCoalRakeToothMaker.dayTimer+dt; if ForgeCoalRakeToothMaker.dayTimer>=30 then ForgeCoalRakeToothMaker.dayTimer=0; for i=#ForgeCoalRakeToothMaker.activeMaking,1,-1 do local m=ForgeCoalRakeToothMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ForgeCoalRakeToothMaker.completeMaking(m); table.remove(ForgeCoalRakeToothMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ForgeCoalRakeToothMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ForgeCoalRakeToothMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ForgeCoalRakeToothMaker.getStats() return {ironStock=ForgeCoalRakeToothMaker.ironStock,bronzeStock=ForgeCoalRakeToothMaker.bronzeStock,woodStock=ForgeCoalRakeToothMaker.woodStock,leatherStock=ForgeCoalRakeToothMaker.leatherStock,silverStock=ForgeCoalRakeToothMaker.silverStock,goldStock=ForgeCoalRakeToothMaker.goldStock,jewelStock=ForgeCoalRakeToothMaker.jewelStock,pearlStock=ForgeCoalRakeToothMaker.pearlStock,productStock=ForgeCoalRakeToothMaker.productStock,numBuildings=#ForgeCoalRakeToothMaker.buildings,hasMaker=ForgeCoalRakeToothMaker.maker~=nil,makerName=ForgeCoalRakeToothMaker.maker and ForgeCoalRakeToothMaker.maker.name or "—",makerSkill=ForgeCoalRakeToothMaker.maker and ForgeCoalRakeToothMaker.maker.skill or 0,activeMaking=#ForgeCoalRakeToothMaker.activeMaking,totalProducts=ForgeCoalRakeToothMaker.totalProducts} end
return ForgeCoalRakeToothMaker
